import { World } from './world.js';
import {loadArt,sceneMarkup,portraitMarkup,artStyle,sceneEntry} from './art.js';
import {lessonHTML,teachingSections,helpHTML,bindHelp,pitfallsHTML,chartHTML,bindDropout,agentTraceHTML} from './learning.js';

const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines = value => esc(Array.isArray(value) ? value.join('\n') : value).replace(/\n/g,'<br>');
const button = (id,text,cls='primary') => '<button id="'+id+'" class="'+cls+'">'+text+'</button>';
let state, curriculum, exercises={}, sourceRegistry={}, toolSchemas=[], diagnostics={}, token='', world, dialogKind=null, currentViewMission=null;
let dirty=false, saveRevision=0, saveQueue=Promise.resolve(), saveTimer, lastInput=Date.now(), paused=false, polling=null, pendingTransfer=null;
let toastTimer, noticeTimer, loading=true, recoveryBlocked=false, importing=false, stateEpoch=0;
const defaults = () => ({version:1,campaignEdition:'persian-v2',location:1,player:{x:500,y:520},currentMission:'m01',completed:[],inventory:[],missions:{},settings:{reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,gentle:true},activeSeconds:0,lastAction:'Вы прибыли к воротам города.',job:null,rehearsal:{remaining:900,interrupted:false},rewardIds:[],ui:null});
function normalize(s) {const d=defaults();const n={...d,...(s||{})};n.settings={...d.settings,...n.settings};for(const k of ['completed','inventory','rewardIds'])if(!Array.isArray(n[k]))n[k]=[];n.missions||={};n.player||=d.player;return n;}
const missions=()=>curriculum?.missions||[];
const mission=id=>missions().find(m=>m.id===id)||missions()[0];
const current=()=>mission(state.currentMission);
function progress(m){
 const p=state.missions[m.id] ||= {};
 const d={stage:0,dialogue:0,draft:'',answer:'',hints:0,attempts:0,status:'familiar',topicAnswers:{},planDone:[]};
 for(const [k,v] of Object.entries(d))if(p[k]===undefined||p[k]===null)p[k]=v;
 p.activity||={};p.checks||={};return p;
}
const unlocked=m=>(m.prerequisites||[]).every(id=>state.completed.includes(id)) && (missions().indexOf(m)===0 || state.completed.includes(missions()[missions().indexOf(m)-1]?.id));
const minutes=s=>Math.floor((s||0)/60)+' мин';
function notify(text){$('#notice').textContent=text;$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,6500);}
function toast(text){$('#worldToast').textContent=text;$('#worldToast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#worldToast').classList.remove('show'),4200);}
async function api(path, body, retried=false){
 const res=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Game-Token':token},body:body===undefined?undefined:JSON.stringify(body)});
 let data;try{data=await res.json();}catch{throw Error('Сервер вернул нечитаемый ответ. Проверьте окно запуска.');}
 if(res.status===403&&body!==undefined&&!retried){
  const fresh=await fetch('/api/bootstrap').then(r=>r.json());
  if(fresh.token&&!fresh.saveError){token=fresh.token;return api(path,body,true);}
 }
 if(!res.ok||data.error)throw Error(typeof data.error==='string'?data.error:JSON.stringify(data.error||data));return data;
}
function changed(delay=650){if(!state||recoveryBlocked||importing)return;dirty=true;saveRevision++;$('#saveStatus').textContent='Сохраняется…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(()=>{}),delay);}
async function save(){if(!dirty||recoveryBlocked||importing)return saveQueue;const rev=saveRevision;const snapshot=structuredClone(state);saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{await api('save',{state:snapshot});if(rev===saveRevision)dirty=false;$('#saveStatus').textContent=dirty?'Сохраняется…':'✓ Сохранено';}catch(e){$('#saveStatus').textContent='⚠ Нет записи';throw e;}});return saveQueue;}
function setWorldPaused(){world?.setPaused(paused||!!dialogKind||document.hidden);}
function showDialog(html,kind='other'){
 dialogKind=kind;$('#dialog').dataset.kind=kind;delete $('#dialog').dataset.stage;
 $('#closeDialog').hidden=['welcome','recovery','error'].includes(kind);
 $('#dialogBody').innerHTML=html;$('#overlay').hidden=false;setWorldPaused();$('#dialog').scrollTop=0;
 const focusTarget=!$('#closeDialog').hidden?$('#closeDialog'):$('#dialogBody button, #dialogBody input');
 focusTarget?.focus({preventScroll:true});
}
function closeDialog(){if(recoveryBlocked)return;$('#overlay').hidden=true;dialogKind=null;currentViewMission=null;paused=false;state.ui=null;changed();setWorldPaused();$('#world').focus();}
function title(kicker,title,sub=''){return '<div class="eyebrow">'+esc(kicker)+'</div><h2 id="dialogTitle">'+esc(title)+'</h2>'+(sub?'<p class="dialog-subtitle">'+esc(sub)+'</p>':'');}
function footer(left,right){return '<div class="dialog-footer"><div>'+left+'</div><div class="right">'+right+'</div></div>';}
function updateHUD(){const m=current(),a=curriculum.acts.find(a=>a.id===state.location)||curriculum.acts[0];$('#actTitle').textContent=a.title;$('#place').textContent=a.place;$('#worldLabel').textContent=a.place||'ГОРОД НЕСКАЗАННЫХ ЖЕЛАНИЙ';$('#missionTitle').textContent=m.title;$('#objective').textContent=m.objective;$('#progressText').textContent=state.completed.length+' из '+missions().length+' главных поручений';$('#progressBar').style.width=(state.completed.length/missions().length*100)+'%';$('#activeTime').textContent=minutes(state.activeSeconds)+' практики';$('#actNav').innerHTML=curriculum.acts.map(a=>'<button class="act-dot '+(state.location===a.id?'active':state.completed.filter(id=>mission(id).act===a.id).length===10?'done':'')+'" data-act="'+a.id+'" aria-label="Акт '+a.id+': '+esc(a.title)+'">'+['I','II','III','IV'][a.id-1]+'</button>').join('');$$('[data-act]').forEach(b=>b.onclick=()=>travel(+b.dataset.act));world?.setMission(m);world?.setReducedMotion(!!state.settings.reducedMotion);}
function travel(act){if(!missions().some(m=>m.act===act&&unlocked(m))){toast('Этот путь откроется по ходу расследования.');return;}state.location=act;state.player={x:500,y:520};world.setState(state);changed();updateHUD();toast(curriculum.acts.find(a=>a.id===act).place);}
function chooseMission(m){if(!unlocked(m)){notify('Сначала завершите предыдущие задания: здесь понадобятся их основы.');return;}state.currentMission=m.id;if(state.location!==m.act){state.location=m.act;state.player={x:500,y:520};world.setState(state);}updateHUD();changed();closeDialog();world.navigateTo?.(m.station);toast('Идите к отмеченному месту и нажмите E.');}
function welcome(){
 const resume=state.completed.length||Object.keys(state.missions).length;
 const html='<div class="welcome-scene">'+sceneMarkup(state.location,'welcome-art')+'<div class="welcome-shade"></div><div class="welcome-content"><div class="eyebrow">ВОСТОЧНЫЙ САД · ИНЖЕНЕРНОЕ ПРИКЛЮЧЕНИЕ</div><h1 id="dialogTitle">persian<br>fairytale. <em>V2</em></h1><p class="welcome-subtitle">Сад точных желаний</p><p>В городе исполнилось безупречное желание.<br>Теперь предстоит понять, что в нём было упущено.</p>'+(resume?'<div class="welcome-resume"><strong>Продолжить с сохранённого места</strong><p>'+esc(state.lastAction)+'</p><small>'+esc(current().objective)+'</small></div>':'<p class="welcome-promise">Исследуйте сад, проводите настоящие эксперименты<br>и собирайте собственную тетрадь исследователя.</p>')+button('begin',resume?'Продолжить путешествие →':'Открыть ворота →')+(state.completed.length?'<div class="welcome-warmup">'+button('warmup','Вспомнить последние открытия','hint-btn')+'</div>':'')+'<div class="welcome-meta"><span>40 ПОРУЧЕНИЙ</span><span>PYTORCH И АГЕНТЫ</span><span>СВОБОДНЫЙ ТЕМП</span></div><p class="edition-note">V2 начинает отдельный учебный маршрут. Сохранения первой версии остаются в её профиле.</p></div></div>';
 showDialog(html,'welcome');if($('#warmup'))$('#warmup').onclick=warmup;
 $('#begin').onclick=()=>{const savedUI=state.ui;closeDialog();if(savedUI?.kind==='mission'&&savedUI.missionId)openMission(mission(savedUI.missionId));else toast('Выберите отмеченное место или нажмите «К месту задания».');};
}
function warmup(){
 const items=state.completed.slice(-3).map(id=>mission(id)).map(m=>({m,t:m.topics[0]}));
 showDialog(title('МЯГКОЕ ВОЗВРАЩЕНИЕ','Три нити памяти','Сначала ответьте про себя или письменно, затем раскройте пример.')+items.map(({m,t},i)=>'<div class="card" style="margin:12px 0"><strong>'+esc(t.name)+'</strong><p>'+esc(t.question)+'</p><details><summary>Вспомнить пример</summary><p>'+lines(t.example)+'</p></details></div>').join('')+footer(button('warmupBack','Назад','secondary'),button('warmupDone','Продолжить путь →')),'warmup');
 $('#warmupBack').onclick=welcome;$('#warmupDone').onclick=()=>{closeDialog();toast(current().objective);};
}

function openMission(m){if(!unlocked(m))return;currentViewMission=m;const p=progress(m);state.ui={kind:'mission',missionId:m.id};changed();renderMission(m);}
function renderMission(m){
 const p=progress(m);currentViewMission=m;const stage=Math.min(4,p.stage||0);const labels=['Встреча','Разобраться','Исследовать','Новый случай','Сохранить вывод'];
 const body=title('АКТ '+m.act+' · '+m.id.toUpperCase()+' · '+labels[stage],m.title,m.objective)+'<div class="steps" aria-label="Этапы поручения">'+labels.map((name,i)=>'<div class="step '+(i<=stage?'on':'')+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(name)+'</div>').join('')+'</div><div id="missionContent"></div>';
 showDialog(body,'mission');$('#dialog').dataset.stage=String(stage);currentViewMission=m;
 if(stage===0)renderDialogue(m,p);if(stage===1)renderLesson(m,p);if(stage===2)renderActivity(m,p);if(stage===3)renderCheck(m,p);if(stage===4)renderReflection(m,p);
}
function advance(m,stage){const p=progress(m);p.stage=stage;state.lastAction='Вы исследуете: '+m.title+'.';changed();renderMission(m);}
function renderDialogue(m,p){
 const story=m.story?.length?m.story:[{speaker:m.npc,text:m.objective}];p.dialogue=Math.min(p.dialogue||0,story.length-1);const line=story[p.dialogue];
 $('#missionContent').innerHTML='<div class="illustrated-dialogue">'+sceneMarkup(m.act,'dialogue-scene')+'<div class="dialogue-shade"></div>'+portraitMarkup(line.speaker,'dialogue-portrait')+'<div class="dialogue-caption"><span class="speaker">'+esc(line.speaker)+'</span><p>'+lines(line.text)+'</p></div></div>'+footer('<span class="muted">'+(p.dialogue+1)+' / '+story.length+' · разговор можно перечитать</span>',(p.dialogue?button('prevLine','←','secondary'):'')+button('nextLine',p.dialogue<story.length-1?'Продолжить →':'Открыть исследование →'));
 if($('#prevLine'))$('#prevLine').onclick=()=>{p.dialogue--;changed();renderDialogue(m,p);};
 $('#nextLine').onclick=()=>{if(p.dialogue<story.length-1){p.dialogue++;changed();renderDialogue(m,p);}else advance(m,1);};
}
function renderLesson(m,p){
 const view=lessonHTML(m,p.lessonPage);p.lessonPage=view.index;
 $('#missionContent').innerHTML=view.html+'<div class="lesson-navigation">'+button('lessonPrev','← Предыдущий шаг','secondary')+'<span>'+(p.lessonPage+1)+' / '+view.sections.length+'</span>'+button('lessonNext','Следующий шаг →','secondary')+'</div>'+((m.teaching?.pitfalls||[]).length?'<details class="lesson-extra"><summary>Типичные затруднения и их причины</summary>'+pitfallsHTML(m.teaching)+'</details>':'')+'<details class="lesson-extra"><summary>Понятия и источники</summary>'+topicHTML(m,p)+'</details>'+(m.teaching?.interview?'<details class="lesson-extra"><summary>Как этот навык пригодится в работе</summary><p>'+lines(m.teaching.interview)+'</p></details>':'')+footer(button('backStory','Перечитать разговор','secondary'),button('toActivity','Перейти к практике →'));
 $('#lessonPrev').disabled=p.lessonPage===0;$('#lessonNext').disabled=p.lessonPage===view.sections.length-1;
 const go=index=>{p.lessonPage=index;changed();renderLesson(m,p);$('#dialog').scrollTop=0;};
 $('#lessonPrev').onclick=()=>go(p.lessonPage-1);$('#lessonNext').onclick=()=>go(p.lessonPage+1);
 $$('[data-lesson-section]').forEach(b=>b.onclick=()=>go(+b.dataset.lessonSection));
 $('#backStory').onclick=()=>advance(m,0);$('#toActivity').onclick=()=>advance(m,2);
 bindTopicInputs(m,p);bindDropout($('#missionContent'));
}
function topicHTML(m,p){return (m.topics||[]).map((t,i)=>'<details class="topic"><summary>'+esc(t.name)+' <span class="badge">'+({apply:'применить',explain:'объяснить',recognize:'назначение'}[t.depth]||esc(t.depth))+'</span></summary><p>'+lines(t.example)+'</p><p><strong>Проверьте себя:</strong> '+esc(t.question)+'</p><textarea data-topic="'+i+'" placeholder="Ответ своими словами; это черновик для самопроверки.">'+esc(p.topicAnswers?.[i]||'')+'</textarea><p class="smallprint">Автоматическая оценка свободного ответа не выполняется. Сопоставьте причинное объяснение с примером и источником.</p>'+(String(sourceRegistry[t.source]?.url||t.source||'').startsWith('https://')?'<a href="'+esc(sourceRegistry[t.source]?.url||t.source)+'" target="_blank" rel="noopener noreferrer">Источник ↗</a>':'<span class="smallprint">Источник: '+esc(t.source)+'</span>')+'</details>').join('');}
function bindTopicInputs(m,p){$$('[data-topic]').forEach(t=>t.oninput=()=>{p.topicAnswers||={};p.topicAnswers[t.dataset.topic]=t.value;changed();});}
function hint(m,p){p.hints=(p.hints||0)+1;p.status='assisted';changed();$('#feedback').innerHTML='<div class="callout warning"><strong>Подсказка наставника</strong><br>'+lines(m.hint||m.remedial)+'</div>';}
function activityShell(m,p,html){
 const ex=m.activity?.type==='code'?exercises[effectiveExercise(m,p)]:null;p.help||={source:ex?'exercise':'mission',page:0};
 $('#missionContent').innerHTML='<div class="practice-layout"><section class="practice-work"><div class="practice-purpose"><div class="eyebrow">ВАША ЗАДАЧА</div>'+lines(ex?.teaching?.goal||m.teaching?.taskBridge||m.objective)+'</div>'+html+'<div id="feedback" aria-live="polite"></div></section><aside id="practiceHelp" class="practice-help" aria-label="Объяснение рядом с практикой">'+helpHTML(m,ex,p.help)+'</aside></div>'+footer(button('activityBack','← Полное объяснение','secondary')+'<br>'+button('hint','Разобрать затруднение','hint-btn'),button('verifyActivity','Проверить действие','primary')+button('activityNext','К новому случаю →','primary'));
 bindHelp($('#practiceHelp'),m,ex,p.help,()=>changed());
 $('#activityNext').disabled=!p.activity.passed;$('#activityBack').onclick=()=>advance(m,1);$('#hint').onclick=()=>hint(m,p);$('#activityNext').onclick=()=>advance(m,3);
}
function activityResult(m,p,passed,text){p.activity.passed=passed;changed();$('#feedback').innerHTML='<div class="callout '+(passed?'success':'warning')+'">'+lines(text)+'</div>';$('#activityNext').disabled=!passed;if(!passed){p.attempts++;if(p.attempts>=2){p.hints++;p.status='assisted';$('#feedback').innerHTML+='<div class="example">'+lines(m.remedial)+'</div>';}}}
function renderActivity(m,p){p.activity||={};const a=m.activity||{};const type=a.type;if(type==='code')return renderCode(m,p);if(type==='threshold')return renderThreshold(m,p);if(type==='split'||type==='compare')return renderSorting(m,p);if(type==='attention')return renderAttention(m,p);if(type==='retrieval')return renderRetrieval(m,p);if(type==='agent')return renderAgent(m,p);activityShell(m,p,'<p>Исследуйте случай: '+esc(m.workedExample)+'</p>');$('#verifyActivity').onclick=()=>activityResult(m,p,false,'Неизвестный тип задания. Сообщите о проблеме: '+type);}
function renderThreshold(m,p){const a=m.activity;p.activity.threshold??=0.5;activityShell(m,p,'<p>'+esc(a.instruction||'Настройте порог риска: страж задерживает пропуск, если score ≥ threshold. Наблюдайте, какие ошибки меняются.')+'</p><label class="field"><span>Threshold — порог решения: <strong id="thresholdValue"></strong></span><input id="threshold" type="range" min="0" max="1" step=".01" value="'+p.activity.threshold+'"></label><div class="grid2"><div><div class="eyebrow">ПРОПУСКА И ПРЕДСКАЗАНИЯ</div><div id="scoreChips" class="chips"></div><p class="smallprint">Опасные пропуска — позитивный класс. Яркие карточки: страж задержал; тусклые: пропустил.</p></div><div><div class="eyebrow">CONFUSION MATRIX</div><div class="matrix" id="matrix"></div></div></div><div class="metrics" id="metrics"></div><p>Условие: Recall опасных пропусков ≥ '+(a.targetRecall??.8)+'; ложных задержаний FP ≤ '+(a.maxFP??2)+'.</p>');function calc(){const threshold=+$('#threshold').value;p.activity.threshold=threshold;const pos=a.positive||[.9,.8,.7,.6,.4],neg=a.negative||[.7,.5,.3,.2,.1];const tp=pos.filter(s=>s>=threshold).length,fp=neg.filter(s=>s>=threshold).length,fn=pos.length-tp,tn=neg.length-fp;$('#thresholdValue').textContent=threshold.toFixed(2);$('#scoreChips').innerHTML=[...pos.map(s=>({s,pos:true})),...neg.map(s=>({s,pos:false}))].map(x=>'<span class="chip '+(x.pos?'good':'bad')+'" style="opacity:'+(x.s>=threshold?1:.4)+'">'+(x.pos?'✓':'×')+' '+x.s.toFixed(2)+(x.s>=threshold?' →':'')+'</span>').join('');$('#matrix').innerHTML='<div>TP <strong>'+tp+'</strong></div><div>FP <strong>'+fp+'</strong></div><div>FN <strong>'+fn+'</strong></div><div>TN <strong>'+tn+'</strong></div>';const prec=tp+fp?tp/(tp+fp):0,rec=tp/(pos.length||1);$('#metrics').innerHTML=[['Precision',prec],['Recall',rec],['F1',prec+rec?2*prec*rec/(prec+rec):0],['Accuracy',(tp+tn)/(pos.length+neg.length)]].map(([s,v])=>'<div class="metric"><strong>'+v.toFixed(2)+'</strong><small>'+s+'</small></div>').join('');return {fp,rec};}calc();$('#threshold').oninput=()=>{p.activity.passed=false;$('#activityNext').disabled=true;calc();changed();};$('#verifyActivity').onclick=()=>{const r=calc();activityResult(m,p,r.rec>=(a.targetRecall??.8)&&r.fp<=(a.maxFP??2),'Recall = '+r.rec.toFixed(2)+', FP = '+r.fp+'. '+(r.rec>=(a.targetRecall??.8)&&r.fp<=(a.maxFP??2)?'Вы нашли допустимое решение. Объясните, почему снижение порога может увеличить ложные задержания.':'Сравните две цены ошибки. При повышении порога положительных решений становится меньше.'));};}
function renderSorting(m,p){const a=m.activity,isSplit=a.type==='split';const cats=isSplit?['train','validation','test']:a.categories||[];const cards=isSplit?(a.records||[]).map(r=>({id:r.id,label:r.label,category:r.group})):a.cards||[];p.activity.assignments||={};activityShell(m,p,'<p>'+esc(a.instruction||(isSplit?'Распределите записи по независимым наборам. Сначала обучаемся, затем выбираем настройки и один раз оцениваем итог.':'Разложите свидетельства по подходящим категориям. Опирайтесь на условия, а не только на знакомое слово.'))+'</p>'+cards.map((c,i)=>'<div class="sort-row"><span>'+esc(c.label)+'</span><select data-sort="'+i+'"><option value="">Выберите место…</option>'+cats.map(cat=>'<option '+(p.activity.assignments[i]===cat?'selected':'')+' value="'+esc(cat)+'">'+esc(cat)+'</option>').join('')+'</select></div>').join(''));$$('[data-sort]').forEach(el=>el.onchange=()=>{p.activity.assignments[el.dataset.sort]=el.value;p.activity.passed=false;$('#activityNext').disabled=true;changed();});$('#verifyActivity').onclick=()=>{const wrong=cards.map((c,i)=>p.activity.assignments[i]!==c.category?i:-1).filter(i=>i>=0);activityResult(m,p,!wrong.length,wrong.length?'Проверьте '+wrong.length+' распределения. Первое расхождение: «'+cards[wrong[0]].label+'». '+(a.feedback||m.remedial):'Все свидетельства на своём месте. Теперь перенесём правило в новый случай.');};}
function renderAttention(m,p){const a=m.activity,q=a.query||[1,0],keys=a.keys||[[1,0],[0,1],[1,1]],values=a.values||keys;p.activity.temperature??=1;activityShell(m,p,'<p>'+esc(a.instruction||'Посмотрите, как query выбирает информацию через сходство с keys. Values — содержимое, которое смешивается с полученными весами.')+'</p><div class="example">Q = ['+q.join(', ')+']<br>Оценка = Q · K / √d; веса = softmax(оценок / T).</div><label class="field"><span>Температура T (для наблюдения за распределением)</span><input id="attTemp" type="range" min=".2" max="3" step=".1" value="'+p.activity.temperature+'"></label><div id="attentionBars"></div><div id="attentionMix" class="callout"></div><label class="field"><span>Какой ключ получает наибольший вес?</span><select id="attChoice"><option value="">Выберите ключ…</option>'+keys.map((k,i)=>'<option value="'+i+'" '+(p.activity.choice===String(i)?'selected':'')+'>K'+(i+1)+' = ['+k.join(', ')+']</option>').join('')+'</select></label>');function draw(){p.activity.temperature=+$('#attTemp').value;const scores=keys.map(k=>k.reduce((s,x,j)=>s+x*(q[j]||0),0)/Math.sqrt(q.length)),exp=scores.map(s=>Math.exp((s-Math.max(...scores))/p.activity.temperature)),den=exp.reduce((a,b)=>a+b),weights=exp.map(e=>e/den);$('#attentionBars').innerHTML=keys.map((k,i)=>'<div>K'+(i+1)+' ['+k.join(', ')+'] · score '+scores[i].toFixed(2)+' · вес '+weights[i].toFixed(3)+'<div class="bar-track"><i style="width:'+(weights[i]*100)+'%"></i></div></div>').join('');const mixed=(values[0]||[]).map((_,j)=>values.reduce((s,v,i)=>s+(v[j]||0)*weights[i],0));$('#attentionMix').textContent='Смесь V = ['+mixed.map(x=>x.toFixed(3)).join(', ')+']. Это вычисление внимания, а не доказательство достоверности текста.';return scores.indexOf(Math.max(...scores));}draw();$('#attTemp').oninput=()=>{draw();changed();};$('#attChoice').onchange=()=>{p.activity.choice=$('#attChoice').value;changed();};$('#verifyActivity').onclick=()=>{const expected=draw();activityResult(m,p,p.activity.choice===String(expected),p.activity.choice===String(expected)?'Верно. Температура меняет резкость весов, но не порядок данных оценок. Проверьте это на двух значениях T.':'Сопоставьте скалярные произведения. Наибольший score получает наибольший вес softmax.');};}
