function pauseMenu(){if(!state)return;if(state.ui?.kind==='mission')state.resumeUI=structuredClone(state.ui);paused=true;interruptRehearsals();changed();showDialog(title('ТИХАЯ ПЕРЕДЫШКА','Город подождёт')+'<p>Игровые события остановлены. Кодовый процесс, если был запущен, может завершиться в фоне. Черновики и положение сохраняются.</p><div class="grid2"><div>'+button('resume','Продолжить →')+'<div class="inline-actions">'+button('saveExit','Сохранить и выйти','secondary')+button('exportSave','Экспорт сохранения','secondary')+'</div><label class="field"><span>Импорт сохранения (заменит текущий прогресс после проверки)</span><input id="importFile" type="file" accept=".json,application/json"></label>'+button('confirmImport','Импортировать выбранный файл','secondary')+'</div><div><label class="field"><input type="checkbox" id="reducedMotion" '+(state.settings.reducedMotion?'checked':'')+'> Уменьшить движение и эффекты</label><p class="smallprint">В основном маршруте нет обязательной моторной сложности. Игра не использует звук или микрофон.</p><p class="smallprint">Учебное время при бездействии более минуты, на паузе и вне окна не накапливается.</p></div></div><details><summary>Диагностика окружения</summary><pre>'+esc(JSON.stringify(diagnostics,null,2))+'</pre><p class="smallprint">Для задач PyTorch нужен import torch в выбранном интерпретаторе. При проблемах используйте отдельную установку зависимостей или notebooks/practice.ipynb в Colab. Colab не подтверждает локальное выполнение и не меняет прогресс автоматически.</p></details><div id="pauseFeedback"></div>','pause');$('#resume').onclick=resumeFromPause;$('#reducedMotion').onchange=()=>{state.settings.reducedMotion=$('#reducedMotion').checked;world.setReducedMotion(state.settings.reducedMotion);changed();};$('#saveExit').onclick=async()=>{try{changed(0);await save();$('#dialogBody').innerHTML=title('ЗАПИСЬ ПОДТВЕРЖДЕНА','До следующей встречи')+'<div class="callout success">Прогресс записан на диск. Теперь можно закрыть вкладку и окно сервера. Для возвращения снова запустите START_GAME.bat.</div>'+button('stay','Остаться в городе','secondary');$('#stay').onclick=closeDialog;}catch(e){$('#pauseFeedback').innerHTML='<div class="callout error">Запись не подтверждена: '+esc(e.message)+'. Не закрывайте игру; восстановите сервер или экспортируйте копию после восстановления связи.</div>';}};$('#exportSave').onclick=exportSave;$('#confirmImport').onclick=()=>importSave($('#importFile').files[0]);}
